import{_ as o,o as r,c as d,a2 as n}from"./chunks/framework.BzFiDlvK.js";const c=JSON.parse('{"title":"开篇 · 课程综述","description":"","frontmatter":{},"headers":[],"relativePath":"guide/intro.md","filePath":"guide/intro.md"}'),e={name:"guide/intro.md"};function a(l,t,i,s,h,g){return r(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="开篇-·-课程综述" tabindex="-1">开篇 · 课程综述 <a class="header-anchor" href="#开篇-·-课程综述" aria-label="Permalink to &quot;开篇 · 课程综述&quot;">​</a></h1><h2 id="🎯-本篇目标" tabindex="-1">🎯 本篇目标 <a class="header-anchor" href="#🎯-本篇目标" aria-label="Permalink to &quot;🎯 本篇目标&quot;">​</a></h2><ul><li>搞清楚这门课到底教什么、按什么顺序教</li><li>想明白「编程能解决什么问题」，给自己一个学下去的理由</li><li>认识 Python 的长处和<strong>短处</strong>——它不是什么都能干</li><li>知道作为「第一门语言」和「第二门语言」学 Python，方法有什么不同</li></ul><hr><h2 id="一、这门课教什么" tabindex="-1">一、这门课教什么 <a class="header-anchor" href="#一、这门课教什么" aria-label="Permalink to &quot;一、这门课教什么&quot;">​</a></h2><p>整门课分成两大块：<strong>基础知识</strong> + <strong>项目实战</strong>。</p><p><strong>基础知识</strong>（第 1–10 章）：</p><table tabindex="0"><thead><tr><th>模块</th><th>你会学到</th></tr></thead><tbody><tr><td>学习编程的方法</td><td>怎么查权威资料、怎么提问、怎么调试</td></tr><tr><td>常用数据类型</td><td>数字、字符串、列表、元组、集合、字典</td></tr><tr><td>判断和循环</td><td><code>if</code> / <code>match</code> / <code>while</code> / <code>for</code>、语句嵌套</td></tr><tr><td>输入输出与文件操作</td><td><code>input</code>、格式化输出、读写文件、文件编码</td></tr><tr><td>函数、类</td><td>定义函数、参数、返回值、面向对象、继承</td></tr><tr><td>模块、标准库、第三方库</td><td>导入、自定义模块、<code>pip</code> 装包</td></tr><tr><td>错误和异常</td><td>异常的捕获与自定义</td></tr></tbody></table><p><strong>项目实战</strong>（第 11–15 章）：</p><table tabindex="0"><thead><tr><th>方向</th><th>你会做出什么</th></tr></thead><tbody><tr><td>数据分析</td><td>采集网页数据 → 存储 → 用图表展示</td></tr><tr><td>办公自动化</td><td>批量读写 Excel / Word，做格式转换</td></tr><tr><td>Web 开发</td><td>用 Django 搭一个自己的博客</td></tr><tr><td>人脸识别</td><td>OpenCV 采集视频、训练模型、识别</td></tr><tr><td>物联网</td><td>ESP32 + MQTT，把室内温度推到手机</td></tr></tbody></table><blockquote><p>📌 顺序不是随便排的：基础知识是<strong>项目实战的前置</strong>。跳过基础直接做项目，会在第 11 章卡住。</p></blockquote><hr><h2 id="二、编程能解决什么问题" tabindex="-1">二、编程能解决什么问题 <a class="header-anchor" href="#二、编程能解决什么问题" aria-label="Permalink to &quot;二、编程能解决什么问题&quot;">​</a></h2><p>作者把「值得用程序解决的事」归成三类：</p><ul><li><strong>重复性劳动</strong>——「脏活」「累活」。每天手动改 500 个 Excel，就该写脚本了。</li><li><strong>复杂的简单问题</strong>——比如「围棋」「斗地主」：规则简单，但人要算很久。</li><li><strong>把生活中的「事儿」归纳成规则</strong>，再交给计算机去交互执行。</li></ul><p>落到具体收益上，有三个方面：</p><table tabindex="0"><thead><tr><th>收益</th><th>含义</th></tr></thead><tbody><tr><td>自动化</td><td>提升工作效率</td></tr><tr><td>定制化</td><td>解决特定问题，而不是迁就现成软件</td></tr><tr><td>数字化</td><td>自动分类、批量处理</td></tr></tbody></table><hr><h2 id="三、python-和其他编程语言的区别" tabindex="-1">三、Python 和其他编程语言的区别 <a class="header-anchor" href="#三、python-和其他编程语言的区别" aria-label="Permalink to &quot;三、Python 和其他编程语言的区别&quot;">​</a></h2><p><strong>Python 的特点：</strong></p><ul><li>是一种<strong>高级编程语言</strong></li><li>是<strong>解释型语言</strong>（写完直接跑，不需要先编译）</li><li>语法和自然语言很像（<code>if x &gt; 0:</code> 读起来就是英文）</li><li>足够流行，应用行业广</li><li>有丰富的库（标准库 + 第三方库）</li></ul><p><strong>Python 不适合的场景</strong>（这一条很重要，别被「Python 万能」带偏）：</p><table tabindex="0"><thead><tr><th>不适合</th><th>原因</th></tr></thead><tbody><tr><td>抢购、电商等<strong>计算密集型</strong>场景</td><td>纯 Python 计算慢；这类场景要 C/C++/Go</td></tr><tr><td><strong>内存等底层硬件操作</strong></td><td>Python 屏蔽了硬件细节，反过来也就做不了精细控制</td></tr><tr><td><strong>网页、小程序等前端开发</strong></td><td>那是 JavaScript / TypeScript 的地盘</td></tr><tr><td><strong>App 开发</strong></td><td>主流是 Kotlin / Swift，不是 Python</td></tr></tbody></table><blockquote><p>💡 一句话：<strong>Python 是&quot;胶水&quot;和&quot;效率工具&quot;</strong>——它擅长把各种轮子粘起来快速解决问题，不擅长榨干硬件性能。</p></blockquote><hr><h2 id="四、该怎么学" tabindex="-1">四、该怎么学 <a class="header-anchor" href="#四、该怎么学" aria-label="Permalink to &quot;四、该怎么学&quot;">​</a></h2><p>课程把学习路径分成两种，对号入座：</p><p><strong>如果 Python 是你的第一门语言：</strong></p><ul><li>编程是门手艺，「我」不是美剧——<strong>两倍速看一遍学不会编程，得多敲代码</strong>。</li><li>关注「用更少的代码解决问题」。</li><li>代码不会永远正确，出问题时记得<strong>调试和跟踪</strong>。</li></ul><p><strong>如果 Python 是你的第二门语言：</strong></p><ul><li>编程不能一蹴而就，要做好<strong>随时重构</strong>的准备。</li><li>关注解释型语言和编译型语言的差异，尤其是<strong>内存分配</strong>方面的异同。</li><li><strong>学会提问</strong>——这是本课程反复强调的能力。</li></ul><blockquote><p>📖 课程指定的必读材料：《提问的智慧》（<em>How To Ask Questions The Smart Way</em>）。 中文版就在本仓库 [00-intro/How-To-Ask-Questions-The-Smart-Way.md(/guide/how-to-ask-questions)。</p></blockquote><hr><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><p><strong>速查表</strong></p><table tabindex="0"><thead><tr><th>问题</th><th>答案</th></tr></thead><tbody><tr><td>课程结构？</td><td>基础知识（第 1–10 章）+ 项目实战（第 11–15 章）</td></tr><tr><td>Python 是什么类型语言？</td><td>高级语言、<strong>解释型</strong>语言</td></tr><tr><td>Python 擅长什么？</td><td>自动化、快速开发、数据分析、脚本胶水</td></tr><tr><td>Python 不擅长什么？</td><td>计算密集型、底层硬件、前端、App</td></tr><tr><td>该怎么学？</td><td>多写、多思考、做好重写的准备</td></tr></tbody></table><p><strong>三句话</strong></p><ol><li>编程语言是工具，目的是提升效率。</li><li>Python 是高级语言，也是解释型语言。</li><li>学 Python 要<strong>多写</strong>、<strong>多思考</strong>、并做好<strong>重写</strong>的准备。</li></ol><p><strong>动手练习（课程课后作业）</strong></p><ol><li>在 C/C++、Python、Java、Go、JavaScript 中，哪种是<strong>编译型</strong>、哪种是<strong>解释型</strong>？ 哪种适合开发操作系统？哪些适合开发 Web 后端程序？</li><li>阅读《提问的智慧》（见上文链接）。</li></ol><hr><p><a href="/zero-basics-python/">返回总目录</a> ｜ <a href="/zero-basics-python/guide/getting-started">下一章：入门的第一道门槛 →</a></p>',42)])])}const b=o(e,[["render",a]]);export{c as __pageData,b as default};
